import sys

def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    MOD = 10**9 + 7
    cnt = [0] * 64
    for x in data[2:2 + n]:
        cnt[int(x)] += 1
    # f[m] = number of elements whose bits include every bit of m
    f = cnt[:]
    for b in range(6):
        for m in range(64):
            if not (m >> b) & 1:
                f[m] += f[m | (1 << b)]
    # g[m] = non-empty subsequences whose AND includes every bit of m
    g = [(pow(2, f[m], MOD) - 1) % MOD for m in range(64)]
    # invert the superset sums: g[m] becomes subsequences whose AND is exactly m
    for b in range(6):
        for m in range(64):
            if not (m >> b) & 1:
                g[m] = (g[m] - g[m | (1 << b)]) % MOD
    print(sum(g[m] for m in range(64) if bin(m).count('1') == k) % MOD)

main()

